namespace MET.City {
public sealed partial class CityInterface {
 void BuildingPage(){var id=_pageContext!=""?_pageContext:SelectedBuilding;if(!S["projects"].Has(id)){Label(_body,"请选择一座建筑。",23);return;}SelectedBuilding=id;var p=S["projects"][id];var st=G.project_stats(id);var identity=Card(_body,G.project_name(id),"T"+p.Get("tier",1).Long+" · "+G.c.operators[p["operator_org"]]["name"].Text+" · 场地 "+p["tile"].Text,Domain(p));var header=Row(identity,"Building Portrait",120);Mark(header,G.c.projects[p["def"]].Get("domain","public").Text,Domain(p),120);var description=Column(header,"Identity",3);Label(description,G.c.projects[p["def"]].Get("description",G.c.projects[p["def"]].Get("summary","")).Text,18,Muted,80);Label(description,p.Get("paused",false).Bool?"暂停运营":p["status"].Text=="construction"?"施工中":"正在运营",20,Gold);
  var actions=Row(identity);if(Development.choices(G,id).Count!=0)Button(actions,"成长与升级",()=>Navigate("upgrades",id),true);Button(actions,p.Get("paused",false).Bool?"恢复运营":"暂停运营",()=>Command(g=>g.set_paused(id,!p.Get("paused",false).Bool)));Button(actions,"拆除（需确认）",()=>Confirm("拆除「"+G.project_name(id)+"」？","支付20通货处理拆除。住户保留并重新安置，库存尝试转仓；仓容不足的实际损耗会记录。",()=>{Command(g=>g.demolish(id),false);SelectedBuilding="";CloseArchive();}),false);
  if(p["status"].Text=="construction"||p.Get("upgrade_job",V.Map()).Count!=0){var job=p.Get("upgrade_job",V.Map()).Count!=0?p["upgrade_job"]:p["job"];var construction=Card(_body,"工程与共享施工能力","升级期间维持当前定义的运营折扣；身份、槽轨与库存不会重置。",Gold);Meter(construction,"实际 CP 完成",job["total"].Double-job["work"].Double,job["total"].Double," CP",Gold);Metric(construction,"尚需材料",F(job["material"].Double));Metric(construction,"全城共享能力",F(Construction.capacity(G))+" CP/月");var priorities=Row(construction);foreach(var value in new[]{-1,0,1}){var v=value;Button(priorities,v==-1?"延后":v==1?"优先":"普通",()=>Command(g=>Construction.set_priority(g,id,v)));}}
  var chain=Card(_body,"真实投入 → 建筑 → 产出","最近周期活动账本；未结算的记录不静态冒充产量。",Blue);var entries=S["metrics"].Get("activity_ledger",V.Map()).Get(id,V.Arr());if(entries.Count==0)Label(chain,"等待实际结算。",17,Muted);foreach(var activity in entries)Label(chain,(activity.Get("kind","").Text=="input"?"投入  →  ":"产出  ←  ")+Resource(activity.Get("resource","").Text)+" "+F(activity.Get("rate",0).Double,3)+" /月"+(activity.Get("kind","").Text!="input"?" · 留 "+F(activity.Get("kept",0).Double,3)+" / 损 "+F(activity.Get("lost",0).Double,3):""),17,activity.Get("kind","").Text=="input"?Gold:Green);
  var run=Card(_body,"用工、运行与库存","人手优先级影响真实分配；服务名额使用真实来源。",Blue);var use=S["metrics"].Get("utilization",V.Map()).Get(id,V.Map());Meter(run,"实际运行",use.Get("utilization",p.Get("usage",0)).Double,1,"",Blue);Metric(run,"岗位容量",F(st.Get("jobs",0).Double)+" 人");if(use.Get("bottleneck","").Text!="")Label(run,use["bottleneck"].Text,17,Gold);var personnel=Row(run);foreach(var value in new[]{-1,0,1}){var v=value;Button(personnel,v==-1?"让出人手":v==1?"优先供人":"普通供人",()=>Command(g=>g.set_priority(id,v)));}foreach(var resource in new[]{"food","material","goods"})if(G.stock_cap_for(id,resource)>0)Meter(run,Resource(resource)+"库存",p["inventory"].Get(resource,0).Double,G.stock_cap_for(id,resource),"",Blue);foreach(var kind in G.c.balance["service_kinds"]){var own=S["metrics"].Get("service_links",V.Arr()).Where(x=>x.Get("source","").Text==id&&x.Get("kind","")==kind).Sum(x=>x.Get("people",0).Double);var cap=st.Get("service."+kind.Text,0).Double;if(cap>0)Meter(run,Service(kind.Text)+"实际服务",own,cap," 人",Blue);}
  var residents=S["groups"].Values.Where(x=>x["host"].Text==id).ToArray();if(residents.Length>0){var home=Card(_body,"本楼住户与生活","实际入住人口加权计算；没有住户时不画健康和幸福。",Green);var total=residents.Sum(x=>x["count"].Double);Meter(home,"入住 / 住房",total,p["status"].Text=="running"?Math.Max(0,st.Get("housing",0).Double*st.Get("efficiency",1).Double):0," 人",Green);foreach(var key in new[]{"health","happiness","education"})Metric(home,V.Map("health","健康","happiness","幸福","education","教育").Get(key,key).Text,F(residents.Sum(x=>x["count"].Double*x.Get(key,0).Double)/Math.Max(.001,total))+" /100");foreach(var kind in new[]{"food","medical","education","commercial","entertainment"})Meter(home,kind=="food"?"实际口粮":Service(kind),residents.Sum(x=>x["count"].Double*x.Get("living",V.Map()).Get(kind,0).Double),total," 人",Blue);}
  var slots=Card(_body,"方案骨架与运营方槽轨","T1 → T2 → T3 每阶解锁一槽；自营记录与原提供方分别保留。",Domain(p));Label(slots,string.Join(" → ",p.Get("slot_track",V.Arr()).Select(x=>Catalog.SLOT_NAMES.Get(x,x).Text)),19,Gold);var rack=Row(slots,"Unlocked Slots",140);foreach(var slotValue in G.slot_ids(id)){var slot=slotValue.Text;var iid=p["slots"][slot].Text;var bid=iid==""?"":S["bonus_instances"][iid]["bonus_id"].Text;var card=Card(rack,G.slot_label(id,slot),bid==""?"空槽":G.c.bonuses[bid]["name"].Text,Blue);Button(card,"管理此槽 ›",()=>Navigate("slot",id+"|"+slot));}
  Fold(_body,"住户、来源与完整规则",c=>{foreach(var group in residents)Raw(c,group);Raw(c,G.compiled.Get("trace",V.Map()).Get(id,V.Map()));Raw(c,S["metrics"].Get("activity_ledger",V.Map()).Get(id,V.Arr()));Raw(c,p["history"]);});
 }
 void UpgradePage(){var id=_pageContext;if(!S["projects"].Has(id))return;var p=S["projects"][id];var choices=Development.choices(G,id);Label(_body,G.project_name(id)+" · T"+p["tier"].Long+" → T"+(p["tier"].Long+1),27,Domain(p));Label(_body,"项目身份、运营方与槽轨持续保留；已有库存不在升级时抹掉。",17,Muted);foreach(var nextValue in choices){var node=nextValue.Text;var view=Development.preview(G,id,node);var card=Card(_body,view["name"].Text,"升级支付 "+F(view["cost"].Double,0)+"通货 · "+F(view["material"].Double,0)+"材料 · "+F(view["construction_required"].Double)+" CP",Gold);Mark(card,G.c.projects[node].Get("domain","public").Text,Domain(p),108);Label(card,"下一槽："+Catalog.SLOT_NAMES.Get(view["slot"],view["slot"]).Text+" · 施工期间运营系数 "+F(view["operation_factor"].Double,2),17,Muted);
   var diffs=Row(card,"Definition Difference",Math.Max(view["gains"].Count,view["losses"].Count)*32+45);var gains=Column(diffs,"Gains",3);Label(gains,"新增与提高",18,Green);foreach(var gain in view["gains"])Label(gains,Stat(gain["stat"].Text)+" "+F(gain["before"].Double)+" → "+F(gain["after"].Double),16,Green);var losses=Column(diffs,"Tradeoffs",3);Label(losses,"减少与代价",18,Gold);foreach(var loss in view["losses"])Label(losses,Stat(loss["stat"].Text)+" "+F(loss["before"].Double)+" → "+F(loss["after"].Double),16,Gold);
   var baseline=_planner.snapshot(G);var clone=_planner.copy_game(G);clone.s["projects"][id]["upgrade_choice"]=node;clone.s["projects"][id]["upgrade_job"]=V.Map("work",0.0,"total",view["construction_required"],"material",0.0,"cp",true);Development.complete(clone,id);clone.refresh_metrics();var error=Sim.tick(clone,G.c.balance["tick_hours"].Double);if(error==""){Metric(card,"同一步升级完成后经营差分",Signed(clone.s["metrics"]["cashflow"].Double-baseline["metrics"].Get("cashflow",0).Double)+" /月");Metric(card,"供电 / 需求能力变化",Signed(clone.s["metrics"]["energy"].Double-baseline["metrics"].Get("energy",0).Double)+" / "+Signed(clone.s["metrics"]["energy_need"].Double-baseline["metrics"].Get("energy_need",0).Double));Button(card,"在地图查看升级完成预测",()=>{_baseline=baseline;_proposal=V.Map("map_snapshot",_planner.display_copy(clone));PublishComparison();ShowForecastMap("proposal",_proposal["map_snapshot"]);});}else Label(card,error,16,Gold);
   Button(card,"确认此方向 · 开始升级",()=>Command(g=>Development.start_upgrade(g,id,node)),true,p["status"].Text!="running"||p["upgrade_job"].Count!=0||S["currency"].Double<view["cost"].Double);Fold(card,"完整建筑定义与同一步来源",c=>{Raw(c,G.c.projects[node]);if(error=="")Raw(c,clone.compiled["trace"].Get(id,V.Map()));});}
 }
 void SlotPage(){var parts=_pageContext.Split('|');if(parts.Length<2||!S["projects"].Has(parts[0]))return;var id=parts[0];var slot=parts[1];var p=S["projects"][id];var iid=p["slots"].Get(slot,"").Text;var rack=Card(_body,G.project_name(id)+" / "+G.slot_label(id,slot),"安装消耗一份真实副本；重签只改变合同组织，原提供方记录保留。",Blue);if(iid!=""){var instance=S["bonus_instances"][iid];var bid=instance["bonus_id"].Text;Label(rack,G.c.bonuses[bid]["name"].Text,25,Gold);Label(rack,"原提供方 "+G.c.operators[instance["provider_org"]]["name"].Text+" · 合同组织 "+G.c.operators[instance.Get("contract_org",instance["provider_org"])]["name"].Text,17,Muted);var actions=Row(rack);Button(actions,"重签为本楼自营 · "+F(G.c.balance["recontract_cost"].Double,0),()=>Command(g=>g.recontract(id,slot)));Button(actions,"拆下当前方案",()=>Command(g=>g.clear_slot(id,slot)));Fold(rack,"已安装规则与历史",c=>{Raw(c,instance);Raw(c,Rules.bonus_rules(G,bid,Math.Max(1,Bonus.active_count(G,bid,"building",id))));});}else Label(rack,"当前为空槽。",20,Muted);
  foreach(var bidValue in Rules.ids(S["block"]["bonus_wallet"])){var bid=bidValue.Text;var license=S["block"]["bonus_wallet"][bid];if(license.Get("charges",0).Long<=0||Bonus.card(G,bid)["scope"].Text!="building")continue;var card=BonusCard(_body,bid);var eligible=G.bonus_eligible(bid,"building",id,slot,iid);var repeat=Bonus.duplicate_preview(G,bid,"building",id);Label(card,eligible==""?"可安装 · "+repeat["note"].Text:eligible,16,eligible==""?Green:Gold);EffectRows(card,repeat["effects"]);if(eligible==""){var forecast=_planner.compare(G,p["def"].Text,p["tile"].Text,V.Map("bonus_id",bid,"provider_org",p["operator_org"],"slot",slot),id,slot);if(forecast.Get("ok",false).Bool)Metric(card,"同一步安装后经营变化",Signed(forecast["cashflow"].Double)+" /月");}Button(card,"消耗1份副本 · 安装",()=>Command(g=>Bonus.install(g,bid,"building",id,slot)),true,eligible!="");}
 }
}
